/**
 * Event names of the latest qlog drafts: namespaces, event type constants, full-name constants, the set of every
 * defined event name, and the full-name -> data type map.
 *
 * Generated by hand from the PUBLISHED drafts and kept honest by names.test.ts, which re-extracts every event name
 * (IANA registrations and event tables), importance level and data type (CDDL rule name) from the draft texts:
 * - draft-ietf-quic-qlog-main-schema-14 §9: `loglevel:*`, `simulation:*`
 * - draft-ietf-quic-qlog-quic-events-13: `quic:*`
 * - draft-ietf-quic-qlog-h3-events-13: `http3:*` and `http:*` (HTTP Capsule Protocol, NOT the pre-final HTTP/3 `http:*`)
 *
 * Usage:
 * ```ts
 * conn.lookup(NS.quic, QUIC.packet_sent);
 * if (ev.fullName === QUIC_EVENTS.packet_sent) { const d = ev.data as EventDataMap["quic:packet_sent"]; ... }
 * ```
 * Replaces qvis's `qlog.EventCategory` / `TransportEventType` / ... enums (data/QlogSchema02.ts).
 */
import type {
    LogLevelDebug,
    LogLevelError,
    LogLevelInfo,
    LogLevelVerbose,
    LogLevelWarning,
    SimulationMarker,
    SimulationScenario,
} from "@/qlog/schema/main";
import type * as Q from "@/qlog/schema/quic";
import type * as H from "@/qlog/schema/h3";

// ================================================================================================
// Namespaces and event schema URIs
// ================================================================================================

/** Namespace identifiers defined by the three drafts. */
export const NS = {
    quic: "quic",
    http3: "http3",
    /** HTTP Capsule Protocol (h3-events-13 §5). Not HTTP/3. */
    http: "http",
    loglevel: "loglevel",
    simulation: "simulation",
} as const;
export type Namespace = (typeof NS)[keyof typeof NS];

/**
 * Final-RFC event schema URIs per namespace. Draft implementations append `-<draft number>` (see
 * {@link EVENT_SCHEMA_DRAFT}), extensions append `#<extension>`; `event_schemas` is a hint only.
 */
export const EVENT_SCHEMA_URI: Readonly<Record<Namespace, string>> = {
    quic: "urn:ietf:params:qlog:events:quic",
    http3: "urn:ietf:params:qlog:events:http3",
    http: "urn:ietf:params:qlog:events:http",
    loglevel: "urn:ietf:params:qlog:events:loglevel",
    simulation: "urn:ietf:params:qlog:events:simulation",
};

/** Draft number whose URI suffix matches the supported drafts (`urn:ietf:params:qlog:events:quic-13`). */
export const EVENT_SCHEMA_DRAFT: Readonly<Partial<Record<Namespace, number>>> = {
    quic: 13,
    http3: 13,
    http: 13,
};

