/** h3-events-13 Table 2: HTTP Capsule Protocol events. */
export const HTTP_EVENT_TYPES = ["capsule_created", "capsule_parsed"] as const;

/** main-schema-14 §9.1 */
export const LOGLEVEL_EVENT_TYPES = ["error", "warning", "info", "debug", "verbose"] as const;

/** main-schema-14 §9.2 */
export const SIMULATION_EVENT_TYPES = ["scenario", "marker"] as const;

export type QuicEventType = (typeof QUIC_EVENT_TYPES)[number];
export type HTTP3EventType = (typeof HTTP3_EVENT_TYPES)[number];
export type HTTPEventType = (typeof HTTP_EVENT_TYPES)[number];
export type LogLevelEventType = (typeof LOGLEVEL_EVENT_TYPES)[number];
export type SimulationEventType = (typeof SIMULATION_EVENT_TYPES)[number];

export type QuicEventName = `quic:${QuicEventType}`;
export type HTTP3EventName = `http3:${HTTP3EventType}`;
export type HTTPEventName = `http:${HTTPEventType}`;
export type LogLevelEventName = `loglevel:${LogLevelEventType}`;
export type SimulationEventName = `simulation:${SimulationEventType}`;

/** Every event name defined by main-schema-14, quic-events-13 and h3-events-13 (57 names). */
export type KnownEventName = QuicEventName | HTTP3EventName | HTTPEventName | LogLevelEventName | SimulationEventName;

type TypeConstants<T extends readonly string[]> = { readonly [K in T[number]]: K };
type FullNameConstants<N extends string, T extends readonly string[]> = {
    readonly [K in T[number]]: `${N}:${K}`;
};

function typeConstants<const T extends readonly string[]>(types: T): TypeConstants<T> {
    return Object.freeze(Object.fromEntries(types.map((t) => [t, t]))) as TypeConstants<T>;
}

function fullNameConstants<N extends string, const T extends readonly string[]>(
    ns: N,
    types: T,
): FullNameConstants<N, T> {
    return Object.freeze(Object.fromEntries(types.map((t) => [t, `${ns}:${t}`]))) as FullNameConstants<N, T>;
}

/** Event TYPE constants (namespace not included): `QUIC.packet_sent === "packet_sent"`. */
export const QUIC = typeConstants(QUIC_EVENT_TYPES);
/** Event TYPE constants: `HTTP3.frame_created === "frame_created"`. */
export const HTTP3 = typeConstants(HTTP3_EVENT_TYPES);
/** Event TYPE constants of the HTTP Capsule namespace: `HTTP.capsule_created === "capsule_created"`. */
export const HTTP = typeConstants(HTTP_EVENT_TYPES);
/** Event TYPE constants: `LOGLEVEL.error === "error"`. */
export const LOGLEVEL = typeConstants(LOGLEVEL_EVENT_TYPES);
/** Event TYPE constants: `SIMULATION.marker === "marker"`. */
export const SIMULATION = typeConstants(SIMULATION_EVENT_TYPES);

/** Full event NAME constants: `QUIC_EVENTS.packet_sent === "quic:packet_sent"`. */
export const QUIC_EVENTS = fullNameConstants(NS.quic, QUIC_EVENT_TYPES);
/** Full event NAME constants: `HTTP3_EVENTS.frame_created === "http3:frame_created"`. */
export const HTTP3_EVENTS = fullNameConstants(NS.http3, HTTP3_EVENT_TYPES);
/** Full event NAME constants: `HTTP_EVENTS.capsule_created === "http:capsule_created"`. */
export const HTTP_EVENTS = fullNameConstants(NS.http, HTTP_EVENT_TYPES);
/** Full event NAME constants: `LOGLEVEL_EVENTS.error === "loglevel:error"`. */
export const LOGLEVEL_EVENTS = fullNameConstants(NS.loglevel, LOGLEVEL_EVENT_TYPES);
/** Full event NAME constants: `SIMULATION_EVENTS.marker === "simulation:marker"`. */
export const SIMULATION_EVENTS = fullNameConstants(NS.simulation, SIMULATION_EVENT_TYPES);

/** Event types per namespace (in draft order). */
export const EVENT_TYPES_BY_NAMESPACE: Readonly<Record<Namespace, readonly string[]>> = {
    quic: QUIC_EVENT_TYPES,
    http3: HTTP3_EVENT_TYPES,
    http: HTTP_EVENT_TYPES,
    loglevel: LOGLEVEL_EVENT_TYPES,
    simulation: SIMULATION_EVENT_TYPES,
};

/** Every event name defined by the three drafts, in draft order (loglevel, simulation, quic, http3, http). */
export const KNOWN_EVENT_NAMES: ReadonlySet<KnownEventName> = new Set<KnownEventName>([
    ...Object.values(LOGLEVEL_EVENTS),
    ...Object.values(SIMULATION_EVENTS),
    ...Object.values(QUIC_EVENTS),
    ...Object.values(HTTP3_EVENTS),
    ...Object.values(HTTP_EVENTS),
]);

/** True if `name` (a full `namespace:type` name, exactly as logged) is defined by one of the three drafts. */
export function isKnownEventName(name: string): name is KnownEventName {
    return (KNOWN_EVENT_NAMES as ReadonlySet<string>).has(name);
}

/** True if `ns` is one of the namespaces defined by the three drafts. */
export function isKnownNamespace(ns: string): ns is Namespace {
    return Object.prototype.hasOwnProperty.call(EVENT_TYPES_BY_NAMESPACE, ns);
}

// ================================================================================================
// Non-conforming names (ARCHITECTURE §3.1 override 2, diagnostic `event.nonconforming-name`)
// ================================================================================================

/**
 * Pre-final qlog categories (draft-02 era and intermediate implementations such as quic-go master) that are not
 * namespaces of the latest drafts. `http` and `simulation` are absent on purpose: they are current namespaces, so a
 * pre-final `http:frame_created` is caught by the "standard namespace but unknown type" rule instead.
 */
export const PRE_FINAL_NAMESPACES: ReadonlySet<string> = new Set([
    "connectivity",
    "transport",
    "security",
    "recovery",
    "qpack",
    "generic",
    "error",
    "warning",
    "info",
    "debug",
    "verbose",
]);

/**
 * Classifies a full event name (exactly as logged; split at the first colon):
 * - `"known"`: defined by main-schema-14 / quic-events-13 / h3-events-13;
 * - `"nonconforming"`: a standard namespace with a type the drafts do not define (`quic:metrics_updated`,
 *   `http:frame_created`), a pre-final category (`transport:packet_sent`), or no namespace at all;
 * - `"private"`: any other namespace (`tcp:`, `tls:`, `http2:` from the converters, or a private schema).
 *
 * Context-dependent exceptions (e.g. a `qpack` namespace listed in the trace's `event_schemas`) are the caller's.
 */
export function classifyEventName(name: string): "known" | "nonconforming" | "private" {
    if (isKnownEventName(name)) return "known";
    const { namespace } = splitEventName(name);
    if (!name.includes(":") || isKnownNamespace(namespace) || PRE_FINAL_NAMESPACES.has(namespace)) {
        return "nonconforming";
    }
    return "private";
}

// ================================================================================================
// Full-name helpers
// ================================================================================================

/** `namespace + ":" + type` (main-schema-14 §8: the name MUST be this concatenation). */
export function fullName<N extends string, T extends string>(namespace: N, type: T): `${N}:${T}` {
    return `${namespace}:${type}`;
}

/**
 * Splits a full name at the FIRST colon (namespaces never contain ":"; the type may). No colon:
 * `{ namespace: "unknown", type: name }`; empty or missing name: `{ namespace: "unknown", type: "unknown" }`
 * (data-model §3.16.4 step 4).
 */
export function splitEventName(name: string | undefined | null): { namespace: string; type: string } {
    if (name === undefined || name === null || name === "") return { namespace: "unknown", type: "unknown" };
    const i = name.indexOf(":");
    if (i < 0) return { namespace: "unknown", type: name };
    return { namespace: name.slice(0, i), type: name.slice(i + 1) };
}

