    // main-schema-14 §9
    "loglevel:error": LogLevelError;
    "loglevel:warning": LogLevelWarning;
    "loglevel:info": LogLevelInfo;
    "loglevel:debug": LogLevelDebug;
    "loglevel:verbose": LogLevelVerbose;
    "simulation:scenario": SimulationScenario;
    "simulation:marker": SimulationMarker;
    // quic-events-13
    "quic:server_listening": Q.QUICServerListening;
